application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');

:root { --ink:#202b35; --muted:#71808c; --line:#dfe7e9; --teal:#137c78; --teal-dark:#0c625e; --cream:#f5f8f6; --coral:#e97862; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:linear-gradient(135deg,#edf5f2 0%,#f9f8f3 55%,#f1f4f5 100%); font-family:'DM Sans',Arial,sans-serif; }
.app-shell { max-width:1120px; margin:0 auto; padding:58px 28px 30px; }
.hero { display:flex; align-items:center; gap:20px; margin-bottom:43px; }
.brand-mark { width:52px; height:52px; display:grid; place-items:center; border-radius:15px; color:#fff; background:var(--teal); font-size:27px; box-shadow:0 8px 20px #137c7833; }
.eyebrow,.section-kicker { margin:0 0 7px; color:var(--teal); font-size:11px; font-weight:700; letter-spacing:1.8px; }
h1,h2,h3,p { margin-top:0; } h1 { margin-bottom:8px; font:700 39px/1.1 'Playfair Display',Georgia,serif; letter-spacing:-.5px; } .intro { margin:0; color:var(--muted); font-size:14px; }
.content-grid { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:25px; align-items:start; }
.panel { border:1px solid #e4ebea; border-radius:18px; background:#fff; box-shadow:0 12px 35px #294b4210; padding:30px; }
.panel-heading { display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:26px; } h2 { margin:0; font:700 24px 'Playfair Display',Georgia,serif; } .step-badge,.count-badge { color:var(--teal); background:#e8f4f1; border-radius:20px; padding:6px 10px; font-size:11px; font-weight:700; } .count-badge { min-width:28px; text-align:center; }
.field-group { margin-bottom:17px; } label { display:block; margin-bottom:8px; font-size:12px; font-weight:700; color:#44545d; } input,select { width:100%; border:1px solid var(--line); border-radius:9px; padding:12px 13px; color:var(--ink); background:#fbfcfc; font:14px 'DM Sans',sans-serif; outline:none; transition:.2s; } input:focus,select:focus { border-color:var(--teal); box-shadow:0 0 0 3px #137c7817; background:#fff; } input:invalid:not(:placeholder-shown) { }
.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; } .field-error { display:block; min-height:0; color:#c85343; font-size:11px; margin-top:5px; } .invalid { border-color:#d96555 !important; background:#fff9f8 !important; }
.primary-button { width:100%; border:0; border-radius:9px; padding:14px 18px; color:#fff; background:var(--teal); cursor:pointer; font:700 14px 'DM Sans',sans-serif; transition:.2s; } .primary-button:hover { background:var(--teal-dark); transform:translateY(-1px); } .primary-button span { margin-left:8px; font-size:18px; vertical-align:-1px; }
.privacy-note { margin:17px 0 0; text-align:center; color:#8a979d; font-size:11px; } .privacy-note span { margin-right:4px; }
.confirmation { margin-top:18px; padding:12px 14px; border-radius:9px; color:#17675e; background:#e9f7f1; font-size:13px; font-weight:600; } .confirmation[hidden] { display:none; }
.booking-list { min-height:250px; } .empty-state { display:flex; min-height:250px; flex-direction:column; align-items:center; justify-content:center; text-align:center; color:var(--muted); } .calendar-icon { display:grid; place-items:center; width:48px; height:48px; margin-bottom:15px; border-radius:14px; color:var(--teal); background:#eaf4f2; font-size:25px; } .empty-state h3 { margin-bottom:6px; font-size:15px; color:#53626a; } .empty-state p { margin:0; font-size:12px; }
.booking-card { position:relative; margin-bottom:12px; padding:18px; border:1px solid #e1eae8; border-left:4px solid var(--teal); border-radius:10px; background:#fcfefd; } .booking-card.cancelled { border-left-color:#aeb9bc; opacity:.68; } .booking-card h3 { margin:0 0 9px; font-size:16px; } .booking-meta { display:grid; gap:6px; color:#687880; font-size:12px; } .booking-meta span { margin-right:5px; } .type-label { display:inline-block; margin-bottom:13px; padding:4px 8px; border-radius:5px; color:var(--teal); background:#e8f4f1; font-size:10px; font-weight:700; } .cancel-button { margin-top:15px; border:0; padding:0; color:#c45f50; background:none; cursor:pointer; font:600 12px 'DM Sans',sans-serif; } .cancel-button:hover { text-decoration:underline; } .cancelled-label { margin-top:15px; color:#7b898d; font-size:12px; font-weight:700; }
footer { margin-top:28px; text-align:center; color:#93a09f; font-size:11px; } footer span { margin:0 7px; color:var(--coral); }
@media (max-width:760px) { .app-shell { padding:35px 17px 24px; } h1 { font-size:32px; } .content-grid { grid-template-columns:1fr; } .panel { padding:23px; } }
@media (max-width:430px) { .form-row { grid-template-columns:1fr; gap:0; } }

application.javascript:
const form = document.getElementById('booking-form');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('booking-confirmation');
const count = document.getElementById('booking-count');
const dateInput = document.querySelector('[data-testid="booking-date"]');
let bookings = [];

function localDateString(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}
dateInput.min = localDateString();

function showError(field, message) {
  const error = document.getElementById(`${field.name}-error`);
  field.classList.toggle('invalid', Boolean(message));
  if (error) error.textContent = message;
}

function validate() {
  const fields = [...form.querySelectorAll('input, select')];
  let valid = true;
  fields.forEach(field => {
    let message = '';
    if (!field.value.trim()) message = 'This field is required.';
    else if (field.type === 'email' && !field.validity.valid) message = 'Enter a valid email address.';
    else if (field.type === 'date' && field.value < dateInput.min) message = 'Choose today or a future date.';
    showError(field, message);
    if (message) valid = false;
  });
  return valid;
}

function formatDate(value) {
  return new Intl.DateTimeFormat(undefined, { weekday:'short', month:'short', day:'numeric', year:'numeric' }).format(new Date(`${value}T00:00:00`));
}
function formatTime(value) {
  const [hour, minute] = value.split(':');
  const d = new Date(); d.setHours(hour, minute);
  return new Intl.DateTimeFormat(undefined, { hour:'numeric', minute:'2-digit' }).format(d);
}
function makeText(tag, className, text) {
  const el = document.createElement(tag);
  el.className = className;
  el.textContent = text;
  return el;
}
function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(el => el.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = bookings.filter(b => !b.cancelled).length;
  bookings.forEach(booking => {
    const card = document.createElement('article');
    card.dataset.testid = 'booking';
    card.dataset.status = booking.cancelled ? 'cancelled' : 'active';
    card.className = `booking-card${booking.cancelled ? ' cancelled' : ''}`;
    card.appendChild(makeText('span', 'type-label', booking.type));
    const name = makeText('h3', '', booking.name);
    name.dataset.testid = 'booking-name-display';
    card.appendChild(name);
    const meta = document.createElement('div');
    meta.className = 'booking-meta';
    meta.appendChild(makeText('div', '', `▣  ${formatDate(booking.date)}`));
    meta.appendChild(makeText('div', '', `◷  ${formatTime(booking.time)}  ·  ${booking.email}`));
    card.appendChild(meta);
    if (booking.cancelled) card.appendChild(makeText('div', 'cancelled-label', 'Cancelled'));
    else {
      const button = makeText('button', 'cancel-button', 'Cancel booking');
      button.type = 'button'; button.dataset.testid = 'booking-cancel';
      button.addEventListener('click', () => { booking.cancelled = true; render(); });
      card.appendChild(button);
    }
    list.appendChild(card);
  });
}
form.addEventListener('submit', event => {
  event.preventDefault();
  confirmation.hidden = true;
  if (!validate()) return;
  const data = new FormData(form);
  const booking = { name:data.get('name').trim(), email:data.get('email').trim(), date:data.get('date'), time:data.get('time'), type:data.get('type'), cancelled:false };
  bookings.push(booking);
  render();
  confirmation.textContent = `Booking confirmed for ${booking.name} on ${formatDate(booking.date)} at ${formatTime(booking.time)}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = localDateString();
});
form.querySelectorAll('input, select').forEach(field => field.addEventListener('input', () => { if (field.value) showError(field, ''); }));
render();
